window.VisualizationTools.chartjs=function(element,json,callback){var canvas=document.createElement('canvas');if(json.width)canvas.width=json.width;if(json.height)canvas.width=json.height;element.appendChild(canvas);loadScript('https://cdnjs.cloudflare.com/ajax/libs/Chart.js/2.7.2/Chart.bundle.min.js').then(function(){new window.Chart(canvas,json.data);callback(element,canvas)}).catch(function(error){console.error('Could not load chartjs.',error)})}